import React from 'react';
import { isElement } from 'react-is';

import { uuidv4 } from '../../../core/utils/uuidv4.js';
import { Annotation } from '../../core/components/annotations-timeseries/types/annotations.js';
import { TrackProps } from '../../core/components/annotations-timeseries/types/tracks.js';
import { Marker } from '../slots/Marker.js';
import { Track } from '../slots/Track.js';
import { AnnotationsMarkerProps } from '../types/annotations-marker-props.js';

export const iterateSlots = (children: React.ReactNode) => {
  const tracks: TrackProps[] = [];
  const aggregatedAnnotations: Annotation[] = [];
  React.Children.forEach(children, (child) => {
    if (isElement(child)) {
      if (child.type === Track) {
        const { children, ...restProps } = child.props;
        const currentTrack = {
          ...restProps,
          markers: [] as AnnotationsMarkerProps[],
        };

        React.Children.forEach(child.props.children, (markerChild) => {
          if (isElement(markerChild)) {
            if (markerChild.type === Marker) {
              const markerProps = { ...markerChild.props, id: uuidv4() };
              currentTrack.markers.push(markerProps);
              aggregatedAnnotations.push(markerChild.props.data);
            }
          }
        });
        tracks.push(currentTrack);
      }
    }
  });

  return { tracks, aggregatedAnnotations };
};
